use super::KernelRule;

pub fn entries() -> Vec<KernelRule> {
    vec![
        // ── D: the boundary-unsplit law — a planned recurrent-state
        // boundary must not END (split) a prefill command; the state is
        // captured INSIDE the running command at planned rows, buffers
        // reserved BEFORE it, checkpoints retired only once their
        // successor is published. ─
        KernelRule {
            rule_id: "mid-prefill-recurrent-state-capture-boundary-unsplit".to_string(),
            gpu_concept: "MECHANISM (mid-command recurrent-state capture: boundary-unsplit prefill for linear-attention/recurrent models; category D — dispatch/serving): a hybrid model's recurrent state (GDN/DeltaNet/Mamba-class) cannot be rewound the way a KV cache rolls a pointer, so every planned state boundary — the replay point, rolling prefill checkpoints, junctions, shared-prefill boundaries — used to END a prefill command so the engine could copy the lane's state after it. THE COST, verbatim (splash `c3dcf53`): 'Every planned state boundary (the replay point, checkpoints, junctions and shared-prefill boundaries) ended a prefill command, and the engine copied the lane\'s state after it.' + 'The replay point lies a few rows before the prompt\'s end, so every turn ran one more small command: 17-24 ms a turn on the 35B and 34-60 ms on the 27B (M5 Max).' THE FIX — CAPTURE INSIDE THE COMMAND (the kernel-adjacent half, splash `711f8e5`, verbatim): 'A prefill command that reaches a state boundary has had to end there: the GDN scan keeps its state in registers and stores it only after its last row.' — so 'ops::GDN::addPrefill now takes the rows after which a prefill captures its state, with the buffers to store it in. It runs the prepare and scan dispatches once per run between them, each run storing its convolution carry and recurrent state as a prefill ending there would and the next run starting from them, and the gate once over all rows.' THE NUMERICS CONTRACT, verbatim: 'The scan is sequential, so with an fp32 state the runs compute exactly what one run does, and a bf16 state is rounded at each captured state as a prefill ending there rounds it. A captured state costs one prepare and one scan dispatch per GDN layer.' (fp32 capture is EXACT by sequential equivalence — the split runs compute the same values one run does; bf16 capture rounds at each capture point exactly as an ended prefill would, so a resumed command reproduces a fresh one bit-for-bit in either dtype). VALIDATION AT ENCODE TIME, verbatim (the throw): 'GDN prefill captures are not ascending inside its rows' — captures must be strictly ascending and interior to the command's rows, checked before anything is submitted. THE RUNTIME HALF (splash `c3dcf53`, verbatim): 'The runtime now captures the states an item lists (ModelBatchItem::stateCaptures) in buffers reserved before the command (Model::reserveState) and returns them in ModelStepResult::capturedStates.' + 'Each state must lie in the item\'s rows with a whole draft window, checked before anything is submitted.' + 'The completion seals the states of a lane that commits; the command\'s ticket keeps the reservations until it has waited for the GPU.' (a failed/cancelled command leaves NOTHING published — the Neural-Engine-rerun guard: 'its context window starts from a copy of the lane\'s, taken once before the command so a Neural Engine rerun does not see the failed run\'s rows'). THE BUFFER LAW (splash `985463c`, verbatim): 'A state captured inside a prefill command needs its buffers before the command runs, while snapshot() takes them after the command and copies the lane into them at once.' — snapshot() decomposes into reserve()/copyState()/seal() ('reserve() takes one cached state\'s GDN cell and context window from the pool, or one admission for what the pool lacks, and nothing on a refusal') and 'A reservation dropped unsealed returns what it still holds to the pool, so each buffer goes back once, and nothing once its storage is gone.' THE RETENTION LAW (splash `79a4329`, verbatim): 'A lane\'s checkpoint now retires only once its successor is published, and gives that successor its buffers only after a command that completed.' — a cancelled, expired or failed command KEEPS the lane's checkpoint and the retry resumes from it: 'on the 35B (M5 Max), each of 8 long prompts cancelled mid-prefill was retried from the last checkpoint it had published, where main restarted 4 of the 8 from the first token.' (retire-BEFORE-write is the lost-checkpoint bug: the successor that never published took the predecessor's buffers, leaving the lane with NO checkpoint at all.) THE CONVERGENCE (four independent implementations; the FlashInfer face, vLLM #60050 MERGED `badfcdbf9`, verbatim): 'a prompt that crosses its cacheable block boundary no longer needs two forward passes: FlashInfer\'s prefill emits the boundary state in the same call' — measured TTFT −20% at concurrency 1, −12% at 4, −10% at 16 (Qwen3.5-35B-A3B, GB200, 8000-token prompts; 'main ran all 336 prompts as 7616 + 384 tokens, and this PR ran every one in a single step with an internal checkpoint'), numerics 'each emitted state matches a separate run truncated at that position (max abs err 5e-3), and the final state is bit-identical with checkpoints on'; the GRID law 'Offsets must be multiples of 64' with the layer-declared alignment (blocks LCM-aligned 1056 → 1088 so checkpoints land on-grid), the FALLBACK 'A checkpoint off it falls back to the split prefill.', and the ADMISSION 'the scheduler takes them only when every Mamba layer can' (Qwen4Exp's PLE short-conv layer cannot export checkpoints — the whole model keeps the split). Mamba2 (#57329) and Kimi-K3 FlashKDA (#52789/#53614) ship the same mechanism. NUMBERS HONESTY: every perf row above is SOURCE-REPORTED provenance (splash M5 Max, vLLM GB200), never an adoption bar; NotBenchable here (no serving-state validator in this corpus). REGIME: hybrid recurrent models with prefix caching / prompt-extension workloads where a state boundary (replay point, checkpoint, junction, shared-prefix boundary) would otherwise split a prefill; the win scales with per-turn boundary count and per-command launch cost (the eliminated 17-60 ms is the small-extra-command cost per turn). ANTI-REGIME: models where every layer CAN export mid-prefill state but none needs to (no boundaries planned — the capture list is empty and the mechanism is inert by construction); a layer that cannot export its state (the PLE short-conv case) vetoes the whole model — fall back to split, never partial-capture; bit-exactness demanded of a bf16-state capture ITSELF (the contract is rounds-as-an-ended-prefill-would, which a resumed command reproduces bit-for-bit — not that the captured bf16 state equals the fp32 one). KINSHIP (do not double-count): gdn-transition-replay-log-commit-many (entries_gpu_08) and the triangular-solve tree-verify rule own SPECULATIVE-VERIFY state algebra (replay/journal + the (I+L)^-1 elimination of per-node states) — a different problem (draft verification) on the same 'a recurrent state is a lossy summary of the whole prefix' ground; THIS owns the SERVING boundary axis (capture-inside-the-command, reserve-before-write, retire-on-publish). prompt-cache-rewind-states-min-gap-evitation (rust-side B219 family) owns KV rewind-state PLACEMENT (min_gap spacing before the latest user turn); THIS owns the recurrent-state CAPTURE MECHANICS — where the state comes from, not where it sits; they compose (the captured checkpoint becomes a rewind state). zero-anchored-prompt-grid-chunk-identity (B215, entries_gpu_84) owns the resumed-cut-equals-fresh-cut grid identity for CHUNKED passes; THIS owns the same identity for the SEQUENTIAL scan's capture points (fp32 exact / bf16 rounds-as-ended — the sequential-equivalence statement) and the boundary-unsplit law that keeps those points INSIDE one command. gpu-resident-control-loop-static-icb-replay (B223) owns GPU-resident control; this owns host-scheduled boundary planning. CITE: incoai/splash (Apache-2.0) @ `711f8e54b47844f090827f8c885f8acdebdc3b6b` (the addPrefill capture loop — the ascending check 'GDN prefill captures are not ascending inside its rows', the per-run prepare/scan dispatches with carry+recurrent spill, the gate-once-over-all-rows, the fp32-exact/bf16-rounds numerics paragraph) + `c3dcf53` (stateCaptures/reserveState/capturedStates, the pre-submit extent checks, the ticket-held reservations, the 17-24/34-60 ms replay-point rows) + `985463c` (reserve/copyState/seal decomposition, the dropped-unsealed return-once law) + `79a4329` (retire-on-publish, the cancelled-retry 8-vs-4 rows) + vllm-project/vllm PR #60050 @ merge `badfcdbf9` (Apache-2.0; the FlashInfer state_checkpoints/every_n emission, the 64-token grid + LCM block alignment, the split-prefill fallback, the all-layers admission, the TTFT table, the max-abs-err-5e-3 / final-state-bit-identical numerics, the Mamba2/Kimi-K3 kinship). Batch 236 / Plan 238 / Research 268.".to_string(),
            ref_shape: "// naive: every planned state boundary ENDS a prefill command. The\n// engine splits the prompt at each boundary (replay point, rolling\n// checkpoints, junctions, shared-prefix boundaries), runs one small\n// extra command per boundary, and copies the lane's state AFTER that\n// command completes. The replay point sits a few rows before the\n// prompt's end, so EVERY turn pays the extra small command: 17-24 ms\n// a turn on the 35B, 34-60 ms on the 27B (M5 Max, source-reported).\n#[derive(Default)]\nstruct EngineTraffic {\n    commands_per_turn: usize,\n    small_extra_commands: usize,\n    checkpoints_lost_on_cancel: usize,\n}\n\n// The GDN scan keeps its state in registers and stores it only after\n// its LAST row -- so a boundary mid-prompt can only be honored by\n// ending the command there.\nfn scan_one_run(state: &mut Vec<f32>, gates: &[f32], inputs: &[f32]) {\n    let dims = state.len();\n    for t in 0..gates.len() {\n        for d in 0..dims {\n            state[d] = gates[t] * state[d] + inputs[t * dims + d];\n        }\n    }\n    // the register state is stored here -- after the last row ONLY\n}\n\nfn prefill_split_at_boundaries(\n    state: &mut Vec<f32>,\n    gates: &[f32],\n    inputs: &[f32],\n    boundaries: &[usize], // planned capture rows (replay point, checkpoints, ...)\n    traffic: &mut EngineTraffic,\n) -> Vec<Vec<f32>> {\n    let mut captured = Vec::new();\n    let mut begin = 0;\n    for &b in boundaries.iter().chain(std::iter::once(&gates.len())) {\n        // one COMMAND per segment: the boundary ENDS the command\n        traffic.commands_per_turn += 1;\n        if b < gates.len() {\n            traffic.small_extra_commands += 1; // the boundary's own small command\n        }\n        scan_one_run(state, &gates[begin..b], &inputs);\n        // snapshot AFTER the command: copy the lane's state out, take\n        // buffers from the pool only now -- a cancelled command leaves\n        // the predecessor ALREADY RETIRED (its buffers were handed to\n        // this boundary before the command ran)\n        captured.push(state.clone());\n        begin = b;\n    }\n    captured\n}\n\nfn cancel_mid_prefill(boundaries: &[usize]) -> usize {\n    // retire-before-write: the successor boundary took the checkpoint's\n    // buffers before the command ran; the cancel publishes nothing and\n    // the retry restarts from the beginning (or an older disk copy)\n    let _ = boundaries;\n    1 // checkpoint lost\n}".to_string(),
            opt_pattern: "// OPT: boundary-unsplit. The prefill command KEEPS its whole row\n// range; each planned boundary is a CAPTURE ROW inside it. The scan\n// runs as split dispatch runs between capture rows -- each run stores\n// its convolution carry and recurrent state AS A PREFILL ENDING THERE\n// WOULD and the next run starts from them; the gate runs once over all\n// rows. Buffers are RESERVED before the command (reserve/seal, not\n// snapshot-after); a lane's checkpoint retires only once its successor\n// is PUBLISHED, so a cancelled command keeps it and the retry resumes\n// there.\n#[derive(Default)]\nstruct EngineTraffic {\n    commands_per_turn: usize,\n    small_extra_commands: usize,\n    checkpoints_lost_on_cancel: usize,\n}\n\nstruct Capture {\n    row: usize,          // the capture row (interior, ascending)\n    recurrent: Vec<f32>, // reserved BEFORE the command\n}\n\nfn scan_runs_between_captures(\n    state: &mut Vec<f32>,\n    gates: &[f32],\n    inputs: &[f32],\n    captures: &mut [Capture],\n    traffic: &mut EngineTraffic,\n) {\n    let dims = state.len();\n    let mut begin = 0;\n    // 'It runs the prepare and scan dispatches once per run between\n    // them, each run storing its convolution carry and recurrent state\n    // as a prefill ending there would and the next run starting from\n    // them, and the gate once over all rows.'\n    for capture in captures.iter_mut() {\n        let end = capture.row;\n        for t in begin..end {\n            for d in 0..dims {\n                state[d] = gates[t] * state[d] + inputs[t * dims + d];\n            }\n        }\n        // the capture: the state AS a prefill ending here would hold\n        capture.recurrent.copy_from_slice(state);\n        begin = end; // the next run starts from them\n    }\n    for t in begin..gates.len() {\n        for d in 0..dims {\n            state[d] = gates[t] * state[d] + inputs[t * dims + d];\n        }\n    }\n    // ONE command for the whole prompt -- no boundary ever splits it\n    traffic.commands_per_turn += 1;\n}\n\n// 'reserve() takes one cached state's GDN cell and context window from\n// the pool, or one admission for what the pool lacks, and nothing on a\n// refusal'; 'A reservation dropped unsealed returns what it still holds\n// to the pool, so each buffer goes back once.'\nstruct Pool {\n    free: usize,\n}\nimpl Pool {\n    fn reserve(&mut self, n: usize) -> Option<Vec<f32>> {\n        if self.free >= n {\n            self.free -= n;\n            Some(vec![0.0; n])\n        } else {\n            None // 'and nothing on a refusal'\n        }\n    }\n    fn release(&mut self, n: usize) {\n        self.free += n; // each buffer goes back once\n    }\n}\n\n// 'GDN prefill captures are not ascending inside its rows' -- the\n// encode-time validation (before anything is submitted)\nfn captures_valid(total_rows: usize, rows: &[usize]) -> bool {\n    let mut previous = 0;\n    for &r in rows {\n        if r <= previous || r >= total_rows {\n            return false; // not ascending / not interior\n        }\n        previous = r;\n    }\n    true\n}\n\n// the retention law: 'A lane's checkpoint now retires only once its\n// successor is published' -- a cancelled command KEEPS it\nstruct Lane {\n    checkpoint: Option<Vec<f32>>,\n    published: bool,\n}\nfn on_command_complete(lane: &mut Lane, successor: Option<Vec<f32>>) {\n    // retire-on-publish: only a COMPLETED command's successor takes the\n    // predecessor's buffers\n    if let Some(s) = successor {\n        lane.checkpoint = Some(s);\n        lane.published = true;\n    }\n}\nfn on_command_cancelled(lane: &mut Lane, traffic: &mut EngineTraffic) {\n    // the cancel publishes nothing; the checkpoint STAYS\n    if lane.checkpoint.is_some() {\n        // nothing lost -- the retry resumes at the checkpoint\n    }\n}\n\nfn toy_stream(n: usize, dims: usize) -> (Vec<f32>, Vec<f32>) {\n    let gates: Vec<f32> = (0..n).map(|i| 0.95 + 0.03 * ((i % 4) as f32)).collect();\n    let inputs: Vec<f32> = (0..n * dims)\n        .map(|i| (((i * 5 + 1) % 13) as f32 - 6.0) * 0.05)\n        .collect();\n    (gates, inputs)\n}\n\n#[test]\nfn no_boundary_splits_the_command() {\n    let (gates, inputs) = toy_stream(200, 4);\n    let boundaries = [64, 128, 190]; // replay point, checkpoints, junction\n    // the naive shape (the incumbent reference, defined locally): every\n    // boundary ENDS a command -- 4 segments for 3 boundaries + the tail\n    let naive_commands = boundaries.len() + 1;\n    let naive_small = boundaries.len();\n\n    let mut opt = EngineTraffic::default();\n    let mut state = vec![0.5f32; 4];\n    let mut captures: Vec<Capture> = boundaries\n        .iter()\n        .map(|&r| Capture { row: r, recurrent: vec![0.0; 4] })\n        .collect();\n    scan_runs_between_captures(&mut state, &gates, &inputs, &mut captures, &mut opt);\n    assert_eq!(opt.commands_per_turn, 1, \"one command, boundary-unsplit\");\n    assert_eq!(opt.small_extra_commands, 0);\n    assert!(opt.commands_per_turn < naive_commands);\n    assert!(opt.small_extra_commands < naive_small);\n\n    // fp32 exactness: one sequential run over all rows == the split runs\n    // ('the runs compute exactly what one run does')\n    let mut one_run = vec![0.5f32; 4];\n    for t in 0..gates.len() {\n        for d in 0..4 {\n            one_run[d] = gates[t] * one_run[d] + inputs[t * 4 + d];\n        }\n    }\n    assert_eq!(state, one_run, \"fp32: the runs compute exactly what one run does\");\n\n    // each capture == a prefill ENDED at that row, from the same start\n    for capture in &captures {\n        let mut ended = vec![0.5f32; 4];\n        for t in 0..capture.row {\n            for d in 0..4 {\n                ended[d] = gates[t] * ended[d] + inputs[t * 4 + d];\n            }\n        }\n        assert_eq!(ended, capture.recurrent, \"capture at row {} == a prefill ending there\", capture.row);\n    }\n}\n\n#[test]\nfn captures_must_be_ascending_and_interior() {\n    assert!(captures_valid(100, &[30, 70]));\n    assert!(!captures_valid(100, &[70, 30]), \"descending\");\n    assert!(!captures_valid(100, &[30, 30]), \"not strictly ascending\");\n    assert!(!captures_valid(100, &[0, 50]), \"not interior (row 0)\");\n    assert!(!captures_valid(100, &[50, 100]), \"not interior (row == total)\");\n    assert!(!captures_valid(100, &[130]), \"past the command's rows\");\n}\n\n#[test]\nfn buffers_reserve_before_and_return_once() {\n    let mut pool = Pool { free: 8 };\n    let a = pool.reserve(4);\n    assert!(a.is_some());\n    let refused = pool.reserve(8); // 'nothing on a refusal'\n    assert!(refused.is_none());\n    assert_eq!(pool.free, 4, \"the refusal took nothing\");\n    pool.release(4); // dropped unsealed: each buffer goes back once\n    assert_eq!(pool.free, 8);\n}\n\n#[test]\nfn cancel_keeps_the_checkpoint_resume_there() {\n    // 'each of 8 long prompts cancelled mid-prefill was retried from\n    // the last checkpoint it had published, where main restarted 4 of\n    // the 8 from the first token' -- the retire-on-publish law\n    //\n    // the naive posture, defined locally (the incumbent reference):\n    // retire-BEFORE-write -- the planned successor took the\n    // predecessor's buffers before the command ran, so the cancel\n    // leaves the lane with NO checkpoint at all\n    let naive_lost = 1;\n    let mut lane = Lane { checkpoint: Some(vec![0.25; 4]), published: true };\n    // opt: the cancel publishes nothing, the checkpoint stays\n    let mut opt = EngineTraffic::default();\n    on_command_cancelled(&mut lane, &mut opt);\n    assert!(lane.checkpoint.is_some(), \"the retry resumes here\");\n    assert_eq!(opt.checkpoints_lost_on_cancel, 0);\n    assert_eq!(opt.checkpoints_lost_on_cancel + 1, naive_lost);\n}".to_string(),
        },
    ]
}
